{
  "name": "@amykit/plugin-file-store",
  "version": "0.8.0",
  "description": "Work records kept as one file per item.",
  "type": "module",
  "license": "MIT",
  "author": "Nicolas Melo",
  "homepage": "https://github.com/nicolasmelo1/amy#readme",
  "bugs": "https://github.com/nicolasmelo1/amy/issues",
  "repository": {
    "type": "git",
    "url": "git+https://github.com/nicolasmelo1/amy.git",
    "directory": "plugins/file-store"
  },
  "publishConfig": {
    "access": "public",
    "registry": "https://registry.npmjs.org"
  },
  "main": "./dist/index.js",
  "types": "./dist/index.d.ts",
  "exports": {
    ".": {
      "types": "./dist/index.d.ts",
      "import": "./dist/index.js"
    }
  },
  "files": [
    "dist"
  ],
  "amy": {
    "about": "Every install that runs an engine needs a record store, and this is the local one: each work record is a JSON file under the state directory. It keeps records only, and briefs go through file-brief-store. Pair it with file-queue and an engine."
  },
  "dependencies": {
    "@amykit/core": "^0.8.0",
    "@amykit/plugin-file-brief-store": "^0.8.0"
  }
}

import fs from "node:fs";
import path from "node:path";
import { Store, WorkRecord, takeLock, writeAtomically } from "@amykit/core";

/** How long a write may take before the lock is judged abandoned. */
const LOCK_LEASE_MS = 10_000;
/** How long a writer waits its turn, counted in turns rather than seconds. */
const LOCK_TURNS = 500;

/** One file per ticket, so a record can be read and edited by hand. */
export class FileStore<R extends WorkRecord = WorkRecord> implements Store<R> {
  constructor(private readonly root: string, create = true) {
    if (create) fs.mkdirSync(this.root, { recursive: true });
  }

  load(workId: string): R | null {
    const file = this.file(workId);
    if (!fs.existsSync(file)) return null;
    return JSON.parse(fs.readFileSync(file, "utf-8")) as R;
  }

  save(record: R): void {
    // Under the record's own lock: a save and a look that read the same
    // record would otherwise write back two versions of it, and whichever
    // renamed last would erase the other's move.
    this.underLock(record.id, () => this.write(record));
  }

  update(workId: string, change: (record: R) => R | undefined): R | null {
    return this.underLock(workId, () => {
      const record = this.load(workId);
      if (record === null) return null;
      const next = change(record);
      if (next !== undefined) this.write(next);
      return next ?? record;
    });
  }

  all(): R[] {
    if (!fs.existsSync(this.root)) return [];
    return fs
      .readdirSync(this.root)
      .filter((name) => name.endsWith(".json"))
      .map((name) => JSON.parse(fs.readFileSync(path.join(this.root, name), "utf-8")) as R);
  }

  /**
   * Written to a name of its own and renamed into place, so a crash
   * mid-write cannot leave a half-written record that fails to parse on the
   * next look, and two writers never share a staged name.
   */
  private write(record: R): void {
    writeAtomically(this.file(record.id), JSON.stringify(record, null, 2));
  }

  private underLock<T>(workId: string, work: () => T): T {
    const lock = `${this.file(workId)}.lock`;
    for (let turn = 0; turn < LOCK_TURNS; turn += 1) {
      const held = takeLock(lock, { leaseMs: LOCK_LEASE_MS });
      if (held) {
        try {
          return work();
        } finally {
          held.release();
        }
      }
      pause(2);
    }
    throw new Error(`could not take ${lock}: another writer held it for ${LOCK_TURNS * 2} ms`);
  }

  private file(workId: string): string {
    return path.join(this.root, `${workId}.json`);
  }
}

/** A synchronous wait, for the turns a held lock costs: this store's API is synchronous. */
function pause(ms: number): void {
  Atomics.wait(new Int32Array(new SharedArrayBuffer(4)), 0, 0, ms);
}

import { ConfigSchema } from "@amykit/core";

/** What this plugin needs told to it, and nothing more. */
export const configSchema = {
  directory: {
    type: "string",
    description:
      "where the records are kept, relative to the state directory. One per workflow, so two profiles under one `.amy` do not read each other's work",
    default: "tickets",
  },
  briefsDirectory: {
    type: "string",
    description:
      "deprecated: where briefs are kept, translated to @amykit/plugin-file-brief-store so existing installs keep their briefs",
  },
} satisfies ConfigSchema;

// Kept as a type-level and runtime import for adapters built before briefs
// became their own mount; the plugin itself now mounts records only.
export { FileBriefStore } from "@amykit/plugin-file-brief-store";
export { FileStore } from "./FileStore.js";
export { configSchema } from "./config.js";
export { plugin } from "./plugin.js";

import path from "node:path";
import { definePlugin } from "@amykit/core";
import { FileStore } from "./FileStore.js";
import { configSchema } from "./config.js";

/** The record store only; briefs mount through their own adapter. */
export const plugin = definePlugin<typeof configSchema>({
  name: "@amykit/plugin-file-store",
  configSchema,
  register(registry, ctx) {
    registry.store(new FileStore(path.join(ctx.paths.state, ctx.config.directory), !ctx.readOnly));
  },
});
